"'$identities=@(Get-Content -LiteralPath (Join-Path $ledger '"'c12-clean-list-tests.txt') | Select-Object -Skip 2 | ForEach-Object { "'$_.Trim() } | Where-Object { $_ })
function Test-Coverage([string[]]$names,[string]$label) {
  $set=[System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
  $names | ForEach-Object { [void]$set.Add($_) }
  $missing=[System.Collections.Generic.List[string]]::new()
  foreach($id in $identities) {
    if($set.Contains($id)){continue}
    $prefix=$id+'"'('
    "'$found=$false
    foreach($n in $set) { if($n.StartsWith($prefix,[System.StringComparison]::Ordinal)){ $found=$true; break } }
    if(-not $found){$missing.Add($id)}
  }
  "$label COVERED=$($identities.Count-$missing.Count)/$($identities.Count) MISSING=$($missing.Count)"
  $missing | ForEach-Object { '"'  ' + "'$_ }
}
$union=[System.Collections.Generic.List[string]]::new()
Get-ChildItem -LiteralPath $ledger -Filter '"'c12-clean*.trx' -File | Sort-Object Name | ForEach-Object {
 [xml]"'$x=Get-Content -LiteralPath $_.FullName -Raw
 $names=@($x.SelectNodes("//*[local-name()='"'UnitTestResult']\") | Where-Object outcome -eq 'Passed' | ForEach-Object {[string]"'$_.testName})
 Test-Coverage $names $_.Name
 $union.AddRange([string[]]$names)
}
Test-Coverage $union.ToArray() '"'UNION'"

